/** Preview acceptance evidence, never a fresh proof or production deployment grant. */
import {readFileSync,lstatSync} from 'node:fs';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import Database from 'better-sqlite3';
import {EXISTING,CARRY_FORWARD,NATIVE_ARTIFACTS,CONTINUITY_QUERIES,requireExistingApproval,verifyHistoricalCandidate,requireRuntimeEquivalence} from './validate-existing-norton-preview.js';
const check=(v:unknown,reason:string):void=>{if(!v)throw Error('Existing Norton handoff refused: '+reason);};
const fileHash=(p:string)=>createHash('sha256').update(readFileSync(p)).digest('hex');
const hash=(v:unknown)=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
const same=(a:unknown,b:unknown,reason:string)=>check(hash(a)===hash(b),reason);
function text(path:string,max=1024*1024){const s=lstatSync(path);check(s.isFile()&&!s.isSymbolicLink()&&s.size>0&&s.size<=max,'bounded regular evidence');return readFileSync(path,'utf8');}
export function verifyExistingNortonHandoff(input:{root:string;directory:string;candidateRoot:string;binding:any;now?:number}){
 const {binding:b}=input,now=input.now??Date.now();
 check(b?.kind==='norton-existing-preview'&&b.repository===EXISTING.repository&&b.pullRequest===176&&b.run?.attempt===1&&b.run.actor===EXISTING.owner&&b.run.triggeringActor===EXISTING.owner&&b.run.event==='workflow_dispatch'&&b.run.path==='.github/workflows/pr.yml','native owner/run purpose');
 const git=(...args:string[])=>execFileSync('git',args,{cwd:input.root,encoding:'utf8'}).trim();
 check(git('rev-parse','HEAD')===b.mergeCommit&&git('rev-parse','HEAD^{tree}')===b.mergeTree&&b.mergeTree===b.auditorTree&&git('rev-parse',b.auditorCommit+'^{tree}')===b.auditorTree,'auditor/merged source chain');
 for(const [key,prefix,max]of[['validationArtifact','existing-preview-validation',1024*1024],['inputsArtifact','existing-preview-inputs',128*1024*1024]]as const){const a=b[key];check(Number.isSafeInteger(a?.id)&&a.id>0&&a.name===`${prefix}-${b.run.id}-attempt-1`&&/^sha256:[a-f0-9]{64}$/.test(a.digest)&&a.bytes>0&&a.bytes<=max&&Date.parse(a.expiresAt)>now,'native artifact binding/retention');}
 const directory=join(input.directory,'continuation'),inputs=join(input.directory,'inputs');
 for(const path of [input.directory,directory,inputs]){const s=lstatSync(path);check(s.isDirectory()&&!s.isSymbolicLink(),'regular artifact directories');}
 const r=JSON.parse(text(join(directory,'continuation-receipt.json'))),live=JSON.parse(text(join(directory,'corpus-live.json'))),edge=JSON.parse(text(join(directory,'edge.json'))),equivalence=JSON.parse(text(join(inputs,'equivalence.json')));
 const completed=Date.parse(r.completedAt);check(Number.isFinite(completed)&&completed<=now+300000&&now-completed<=7*86400000,'bounded preview acceptance age');
 check(r.schemaVersion==='norton-existing-preview-validation-receipt.v1'&&r.purpose==='postdeployment-preview-validation-only'&&r.custody===true&&r.checks===370,'successful validation-only receipt');
 same(r.candidate,{sourceCommit:EXISTING.sourceCommit,sourceTree:EXISTING.sourceTree,worker:EXISTING.worker,deployment:EXISTING.deployment,database:EXISTING.database,workerSha256:EXISTING.workerSha256},'deployed candidate identity');
 same(r.auditor,{commit:b.auditorCommit,tree:b.auditorTree},'distinct reviewed auditor');requireExistingApproval(r.authority,{commit:b.auditorCommit,tree:b.auditorTree},completed);
 check(r.operationId===r.authority.operationId&&r.ownerDispatch?.runId===String(b.run.id)&&r.ownerDispatch.ownerActorId===EXISTING.owner&&r.ownerDispatch.triggeringActorId===EXISTING.owner&&r.ownerDispatch.auditorCommit===b.auditorCommit&&r.ownerDispatch.auditorTree===b.auditorTree&&r.ownerDispatch.operationId===r.operationId,'native receipt/owner operation');
 check(equivalence.schemaVersion==='norton-fixed-runtime-equivalence.v1'&&equivalence.candidateSourceCommit===EXISTING.sourceCommit&&equivalence.auditorCommit===b.auditorCommit&&equivalence.auditorTree===b.auditorTree&&equivalence.admission?.runId===String(b.run.id)&&equivalence.admission.operationId===r.operationId,'same-run input/source attestation');
 same(r.runtimeEquivalence,equivalence,'native runtime attestation bytes');
 const runtime=requireRuntimeEquivalence(input.root,join(inputs,'auditor-bundle'));same(runtime.inputs,equivalence.inputs,'merged runtime/data/fixture equivalence');check(runtime.workerSha256===EXISTING.workerSha256&&equivalence.workerSha256===EXISTING.workerSha256,'compiled Worker identity');
 // Original ZIPs need not still exist at production time: immutable files and the
 // source job's dated original-native metadata survive in this SUCCESS run's inputs.
 for(const captured of [equivalence.admission.nativeArtifacts,r.ownerDispatch.nativeArtifacts]){check(Array.isArray(captured)&&captured.length===4,'original native chain retained');for(const expected of NATIVE_ARTIFACTS){const a=captured.find((x:any)=>x.id===expected.id);check(a?.name===expected.name&&a.digest===expected.digest&&a.originalRunId===EXISTING.run&&a.originalSourceCommit===EXISTING.sourceCommit&&Date.parse(a.expiresAt)>completed,'original inputs nonexpired at validation');}}
 const historical=verifyHistoricalCandidate(inputs,input.candidateRoot);
 check(r.historicalProof?.sha256===EXISTING.proofSha256&&r.historicalProof.completedAt===historical.historicalVerificationAt&&r.historicalProof.historicalValidationClock===historical.historicalVerificationAt&&r.historicalProof.freshProof===false&&r.historicalProof.structurallyReverifiedAsHistorical===true&&r.historicalProof.validationDay===EXISTING.validationDay&&r.historicalProof.maximumAgeMsApproved===EXISTING.maximumHistoricalProofAgeMs&&r.historicalProof.ageAtValidationMs===completed-Date.parse(EXISTING.proofCompletedAt),'explicit historical proof age, never fresh');
 same(r.quotaPolicy,{accountReadCeiling:4400000,analyticsMargin:200000,previousReadReservation:3860000,finalHeldReadReservation:3960000,carriedForwardRole:CARRY_FORWARD},'held role and approved ceiling');
 check(r.metering?.rowsWritten===0&&Number.isSafeInteger(r.metering.controlRequests)&&r.metering.controlRequests>=0&&r.metering.controlRequests<=32&&Number.isSafeInteger(r.metering.continuityRowsRead)&&r.metering.continuityRowsRead>=0&&r.metering.continuityRowsRead<=8960&&r.metering.liveReadsReserved===90000&&r.metering.newTotalReadsReserved===100000&&r.metering.knownPriorReads===EXISTING.knownPriorReads,'read-only bounded metering');
 check(live.schemaVersion==='norton-aquinas-live.v1'&&live.role==='preview'&&live.endpoint==='https://preview-mcp.theologai.xyz/mcp'&&live.serverVersion===JSON.parse(text(join(input.root,'package.json'))).version+'-preview'&&live.productProfile==='7'&&!Object.hasOwn(live,'failure')&&live.broaderV9Features===false&&live.sourceBodyOutput===false&&Number.isSafeInteger(live.durationMs)&&live.durationMs>=0&&live.durationMs<=600000&&Number.isSafeInteger(live.aggregateResponseBytes)&&live.aggregateResponseBytes>=0&&live.aggregateResponseBytes<=16*1024*1024,'complete bounded corpus-only live result');
 check(live.manifestSha256===fileHash(join(input.root,'data/data-manifest.json'))&&live.fixtureSha256===hash(['historical-core-preview-audit','historical-spine-preview-audit','original-language-v2-preview-audit'].map(name=>JSON.parse(text(join(input.root,'test/fixtures/'+name+'.json'))))),'exact source manifest and live fixtures');
 same(live.protocols,['2025-11-25','2026-07-28'],'both protocols');same(r.protocols,live.protocols,'receipt protocols');check(Array.isArray(live.checks)&&live.checks.length===370,'370 checks');
 for(const era of live.protocols){const checks=live.checks.filter((c:any)=>c.era===era);check(checks.length===185&&new Set(checks.map((c:any)=>c.id)).size===185&&checks.every((c:any)=>c.passed===true&&c.role==='preview'&&/^[a-f0-9]{64}$/.test(c.responseSha256)),'all unique era checks passed');const summary=live.summaries?.find((s:any)=>s.era===era);check(summary?.checks===185&&summary.httpExchanges<=200,'per-era transport bound');}
 same(live.checks.filter((c:any)=>c.era===live.protocols[0]).map((c:any)=>c.id),live.checks.filter((c:any)=>c.era===live.protocols[1]).map((c:any)=>c.id),'matching complete era operations');same(live.fingerprints[0],live.fingerprints[1],'dual-era contract');check(live.databaseSha256===EXISTING.databaseSha256&&r.liveSha256===hash(live)&&edge.passed===true&&edge.audit==='primary-source-edge-stabilization-preview'&&edge.endpointClass==='preview-custom'&&r.edgeSha256===hash(edge),'native report/source/edge hashes');
 const expectedControls=[{role:'production',deploymentId:EXISTING.productionDeployment,versionId:EXISTING.productionWorker,databaseId:EXISTING.productionDatabase},{role:'preview',deploymentId:EXISTING.deployment,versionId:EXISTING.worker,databaseId:EXISTING.database}];same(r.before,expectedControls,'initial assignments');same(r.after,r.before,'unchanged final assignments');
 for(const [name,initial]of[['initialUsage',true],['finalUsage',false]]as const){const u=r[name],total=u?.candidate?.rowsRead+u?.otherDatabases?.rowsRead;check(u?.accountId===EXISTING.account&&u.databaseId===EXISTING.database&&u.completeDatabaseGroups===true&&u.windowStart===EXISTING.validationDay+'T00:00:00.000Z'&&Number.isSafeInteger(total)&&total>=0&&u.candidate.rowsWritten===0&&u.otherDatabases.rowsWritten<=80000,'complete current-day read-only quota');check((initial?Math.max(total,3860000)+100000:Math.max(total,3960000))+200000<=4400000,'full role and margin');if(!initial)check(completed-Date.parse(u.capturedAt)>=0&&completed-Date.parse(u.capturedAt)<=50000,'fresh final usage');}
 const events=text(join(directory,'continuation.events.jsonl'),4*1024*1024).trim().split('\n').map(line=>JSON.parse(line));check(!events.some(e=>e.kind==='STOP')&&events.at(-1)?.kind==='continuation-complete'&&events.at(-1).receiptSha256===hash(r),'terminal completion, no STOP');
 const db=new Database(join(inputs,'source/source.db'),{readonly:true,fileMustExist:true});let reads=0;
 try{for(const phase of ['before','after'])for(const q of CONTINUITY_QUERIES){const rows=events.filter(e=>e.kind==='select-result'&&e.phase===phase&&e.label===q.label);check(rows.length===1,'complete unique continuity readbacks');const e=rows[0],expected=q.label==='schema'?historical.envelope.receipt.proof.catalogSha256:q.label==='ledger'?historical.envelope.receipt.proof.ledgerSha256:hash(db.prepare(q.sql).all());check(e.rowsWritten===0&&e.changes===0&&Number.isSafeInteger(e.rowsRead)&&e.rowsRead>=0&&e.rowsRead<=q.ceiling&&e.responseSha256===expected,'exact read-only continuity witness');reads+=e.rowsRead;}}finally{db.close();}
 check(reads===r.metering.continuityRowsRead,'complete continuity metering');
 return{kind:'norton-existing-preview-acceptance',freshPreviewProof:false,productionAuthorized:false,candidate:r.candidate,auditor:r.auditor,merge:{commit:b.mergeCommit,tree:b.mergeTree},nativeRun:b.run.id,checks:370,receiptSha256:hash(r)};
}
